"""Explain local-lock debug representation, initialization and context."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1405': ('작업 규칙을 지키는 장치와 누가 작업 중인지 적는 관찰 기록은 다릅니다. 기록장을 빼도 작업 규칙을 지키는 장치가 남아 있을 수 있습니다.', '빈 자료 구조와 실제 보호 동작을 구별합니다.', 'non-RT에서 디버그 켜짐: dep_map·owner 있음, 디버그 꺼짐: 두 필드 없음이라고 적으세요. 두 경우 모두 기본 wrapper에는 preempt_disable이 남는다고 연결하세요.', ['이 수업은 CONFIG_PREEMPT_RT가 꺼진 일반 구성입니다. local_lock_t는 여러 정보를 묶는 struct, 즉 구조체로 정의됩니다. 어떤 정보가 들어가는지는 또 다른 디버그 설정에 따라 달라집니다.', 'CONFIG_DEBUG_LOCK_ALLOC이 켜지면 dep_map과 owner 필드가 들어갑니다. dep_map은 잠금 관계를 분석하는 도구의 기록이고 owner는 현재 보유 작업을 가리키는 값입니다. 실제로 공용 잠금 비트를 저장하는 spinlock 필드는 이 구조에 없습니다.', '디버그 설정이 꺼지면 두 필드가 모두 빠져 빈 구조체가 됩니다. 이는 커널이 사용하는 GNU C 문법의 맥락에서 읽어야 합니다. 모든 표준 C 환경이 빈 구조체를 똑같이 허용한다고 가정하면 안 됩니다.', '이때 local_lock_acquire, local_lock_release, local_lock_debug_init도 본문이 빈 함수가 됩니다. 분석용으로 기록하거나 검사할 정보가 없으므로 그 동작을 하지 않는 것입니다.', '그러나 바깥 __local_lock에는 먼저 preempt_disable을 하는 코드가 있습니다. 다른 작업으로 선점되는 것을 막아 현재 CPU 자료를 보호하는 역할은 분석 함수가 비었다고 사라지지 않습니다. IRQ 변형은 그에 맞는 인터럽트 제어를 수행합니다.', '구조체의 크기나 한 함수의 빈 본문만 보고 전체 API가 아무 일도 하지 않는다고 결론 내리지 마세요. 호출하는 바깥 매크로와 빌드 설정을 함께 읽어야 실제 보호 동작을 알 수 있습니다. RT 구성은 자료형과 구현이 별도로 달라집니다.'], [('일반 non-RT 구성에서 디버그가 꺼진 local_lock_t에 반드시 spinlock 필드가 있을까요?', ['네. 언제나 64비트 잠금 필드가 있어요', '아니요. 빈 구조체일 수 있어요'], '이 구조체의 필드는 디버그용 두 개이며 설정이 꺼지면 빠집니다. 실제 동작을 알려면 바깥의 문맥 제어 코드도 확인해야 합니다.'), ('local_lock_acquire가 빈 함수면 기본 local_lock의 보호도 모두 없어질까요?', ['아니요. 바깥 wrapper의 선점 제어가 남아요', '네. 호출 전체가 아무 일도 하지 않아요'], '__local_lock은 빈 분석 함수에 들어가기 전에 preempt_disable을 호출합니다. 분석 기록의 생략과 실행 문맥 보호의 생략은 다릅니다.')]), 'os1406': ('공책 사용 기록에 누가 쓰는지 적고, 돌려주는 사람이 그 사람인지 확인합니다. 이 기록은 잘못된 사용을 찾는 데 도움이 되지만 문을 실제로 잠그는 장치와는 다릅니다.', '디버그 owner 기록의 변화와 분석 도구의 역할을 이해합니다.', '정상 흐름 owner=NULL → A가 획득하여 owner=A → A가 해제하여 NULL을 쓰세요. A가 보유한 상태에서 B가 해제하려는 경우는 경고 조건이라고 표시하세요.', ['일반 구성에서 DEBUG_LOCK_ALLOC이 켜지면 local_lock_acquire가 기록을 관리합니다. current는 지금 실행 중인 task를 가리킵니다. task는 커널이 실행을 관리하는 작업 단위입니다.', '먼저 lock_map_acquire로 lockdep 분석 도구에 획득을 알립니다. 이어 owner가 이미 있는지 DEBUG_LOCKS_WARN_ON으로 확인합니다. 이미 보유 기록이 있는데 또 획득하는 잘못된 흐름을 찾기 위한 조건입니다.', '그다음 owner=current를 저장합니다. 정상적으로 A가 얻었다면 owner는 A입니다. owner를 적는 것이 모든 CPU를 실제 잠금으로 막는 원자적 획득 명령은 아닙니다. 보호 동작은 상위의 실행 문맥 제어와 함께 읽어야 합니다.', '해제에서는 owner != current인지 확인합니다. A가 가진 기록인데 B가 해제하려 하면 맞지 않습니다. 정상 A 해제에서는 owner를 NULL로 지우고 lock_map_release로 분석 도구에 해제를 알립니다.', 'NULL은 여기서 보유 작업이 없다는 표시입니다. 초기화 함수 local_lock_debug_init도 owner=NULL을 기록합니다. 획득 때 NULL→current, 해제 때 current→NULL이라는 정상 짝을 따라가면 됩니다.', '경고는 잘못된 사용을 알려 주는 진단입니다. 경고가 다른 작업의 사용을 정상적으로 기다려 주거나 안전하게 고쳐 주는 동기화 수단이라고 생각하면 안 됩니다. 이 기록이 없는 빌드에서도 올바른 보호 규칙을 지켜야 합니다.'], [('정상적인 디버그 acquire 뒤 owner에는 무엇이 들어갈까요?', ['항상 NULL이에요', '현재 작업을 뜻하는 current예요'], '원문이 owner=current를 대입합니다. NULL로 되돌리는 것은 정상 해제나 초기화 단계입니다.'), ('owner와 lockdep 기록 자체가 모든 CPU에 대한 전역 잠금을 얻을까요?', ['아니요. 분석을 위한 기록이에요', '네. 기록 하나가 모든 CPU를 직렬화해요'], '보유 관계를 기록하고 진단하는 역할입니다. 실제 선점 제어 또는 RT의 CPU별 spinlock과 구별해야 하며 기록만으로 공유 자료 보호를 대신할 수 없습니다.')]), 'os1407': ('기록장을 처음 만들 때 이름표와 분류표를 붙입니다. 분류표가 함수 호출이 끝나자마자 사라지면 나중의 기록을 이어서 해석하기 어렵습니다.', '잠금 초기화의 이름·분류 키·유형과 수명을 이해합니다.', '__local_lock_init 옆에는 static key·LD_LOCK_PERCPU, __spinlock_nested_bh_init 옆에는 static key·LD_LOCK_NORMAL이라고 적어 공통점과 차이를 비교하세요.', ['초기화는 잠금과 분석 정보를 처음 쓸 수 있도록 준비하는 과정입니다. 일반 구성의 INIT_LOCAL_LOCK은 디버그 설정에 따라 초기 필드 값을 만듭니다. 아직 다른 작업이 사용하지 않는 시점에 준비해야 합니다.', '디버그 초기값에는 이름, 기다림 종류, 잠금 종류, owner=NULL이 있습니다. #lockname은 매크로 인자 이름을 문자열로 만드는 C 전처리 문법입니다. 숫자 연산이 아니라 도구에 보여 줄 이름을 붙입니다.', '실행 중 호출하는 __local_lock_init에는 static struct lock_class_key __key가 있습니다. key는 분석 도구가 잠금 종류를 구별하는 표식입니다. static이라 함수 호출이 끝날 때 사라지는 보통의 지역 임시 값과 수명이 다릅니다.', 'debug_check_no_locks_freed로 관련 잘못된 상태를 검사하고 lockdep_init_map_type으로 이름·키·유형을 등록합니다. 마지막 local_lock_debug_init은 owner를 비웁니다. 분석 기능을 끈 구성에서는 관련 기록과 검사가 생략될 수 있습니다.', '비슷한 __spinlock_nested_bh_init도 같은 순서의 준비를 하지만 마지막 유형은 LD_LOCK_NORMAL입니다. __local_lock_init의 LD_LOCK_PERCPU와 다릅니다. 비슷한 이름만 보고 같은 분류값이라고 읽지 말고 실제 인자를 비교하세요.', '초기화는 이미 누가 보유한 잠금을 마음대로 지우는 방법이 아닙니다. 사용 중 재초기화하면 분석 기록과 실제 사용 관계가 맞지 않게 될 수 있습니다. 공개 전 초기화, 올바른 사용, 수명 종료라는 순서를 지키세요.'], [('실행 중 초기화 매크로의 __key는 호출 끝에 사라지는 임시 변수일까요?', ['네. 매번 스택에만 잠깐 존재해요', '아니요. static으로 선언돼요'], '원문은 static struct lock_class_key입니다. 분석 분류에 쓰는 표식을 유지하므로 일반 지역 임시 값과 구별해야 합니다.'), ('비교한 nested BH 초기화의 잠금 유형은 무엇일까요?', ['LD_LOCK_NORMAL이에요', '두 초기화 모두 언제나 LD_LOCK_PERCPU예요'], '두 매크로의 마지막 유형 인자가 다릅니다. 일반 local 초기화는 PERCPU, 비교 대상 nested BH 초기화는 NORMAL입니다.')]), 'os1408': ('우리 교실 공책을 고치는 동안 담당 작업이 다른 작업으로 바뀌지 않게 합니다. 하지만 긴급 호출인 인터럽트까지 모두 막은 것은 아닙니다.', '기본 non-RT local_lock의 실행 순서와 IRQ 보호의 차이를 이해합니다.', '선점 금지 → 현재 CPU 잠금 기록 → 자료 사용 → 기록 해제 → 선점 금지 복구 순서를 그리세요. 기본 경로에는 IRQ 차단 호출이 없다고 적으세요.', ['이 수업은 PREEMPT_RT가 아닌 기본 local_lock 경로입니다. __local_lock 매크로는 먼저 preempt_disable을 호출합니다. 선점은 실행 중인 작업을 멈추고 다른 작업이 CPU를 쓰도록 바꾸는 것입니다.', '그 뒤 this_cpu_ptr(lock)로 현재 CPU에 대응하는 잠금 위치를 고르고 local_lock_acquire를 호출합니다. 먼저 선점 제어를 하여 보호 구간에서 현재 CPU의 자료를 일관되게 다루는 조건을 만듭니다.', 'local_lock_acquire는 디버그 구성에서 분석 기록을 하고 아니면 빈 함수입니다. 기본 non-RT 경로가 다른 CPU와 공유하는 전역 잠금에 원자적 연산을 추가하는 것은 아닙니다. CPU별 자료와 그 자료에 접근하는 실행 문맥을 대상으로 합니다.', '대응 __local_unlock은 현재 CPU의 기록을 해제한 다음 preempt_enable로 이번 금지를 되돌립니다. 처음과 끝을 짝지어야 하고 보유 구간에서 잠드는 호출을 넣으면 안 됩니다. 원래 금지 횟수가 1이면 획득 때 2, 해제 때 다시 1입니다. 이전 금지까지 모두 없애는 것이 아닙니다.', '기본 경로에는 local_irq_disable이 없습니다. hard IRQ는 하드웨어 인터럽트를 처리하는 실행이며, 선점 금지만으로 그런 진입까지 항상 막지는 않습니다. IRQ에서 같은 자료를 만지면 기본 local_lock만 충분하다고 단정할 수 없습니다.', 'IRQ 변형이나 irqsave 변형은 해당 문맥에 맞춘 제어를 따로 제공합니다. 어떤 코드가 같은 자료를 만지는지 확인해 올바른 변형과 해제를 짝지으세요. 다른 CPU의 자료를 직접 바꾸는 경우도 이 local 보호와 별도로 검토해야 합니다.'], [('기본 non-RT local_lock은 어떤 순서로 시작할까요?', ['CPU를 고른 뒤 언제나 migration을 허용해요', '선점을 금지한 뒤 현재 CPU의 획득 기록으로 연결해요'], '원문은 preempt_disable 다음 local_lock_acquire(this_cpu_ptr(lock))입니다. 현재 CPU 자료를 사용하는 문맥 제어 순서가 중요합니다.'), ('기본 local_lock만 쓰면 hard IRQ 진입도 언제나 막힐까요?', ['아니요. IRQ 변형과 접근 문맥을 확인해야 해요', '네. 모든 인터럽트도 자동으로 차단해요'], '기본 경로에는 local_irq_disable이 없습니다. 선점 제어와 인터럽트 제어는 역할이 달라 같은 자료에 접근하는 문맥에 맞는 변형이 필요합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_347.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
